package helper

import (
	"context"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/sha256"
	"crypto/x509"
	"encoding/hex"
	"encoding/pem"
	"errors"
	"strings"
	"time"

	"github.com/davdxpx/ExponetDB/agent/node/internal/canon"
	"github.com/davdxpx/ExponetDB/agent/node/internal/clock"
	"github.com/davdxpx/ExponetDB/agent/node/internal/config"
	"github.com/davdxpx/ExponetDB/agent/node/internal/fsafe"
	"github.com/davdxpx/ExponetDB/agent/node/internal/nodecrypto"
	"github.com/davdxpx/ExponetDB/agent/node/internal/verify"
)

// Staged TLS keys (OD-17): generated by postgres.tls.plan, installed by
// postgres.tls.rotate, removed after a day or on installation.
const (
	stagedKeySuffix = ".key"
	stagedKeyTTL    = 24 * time.Hour
	maxStagedKeys   = 16
	crockford       = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
)

func newStagingID() (string, error) {
	var b [26]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", err
	}
	for i := range b {
		b[i] = crockford[b[i]&31]
	}
	return string(b[:]), nil
}

func validStagingID(id string) bool {
	if len(id) != 26 {
		return false
	}
	for _, c := range id {
		if !strings.ContainsRune(crockford, c) {
			return false
		}
	}
	return true
}

// staging opens the staging directory: root's, never accessible to others.
func (h *Helper) staging() (*fsafe.Dir, *Refusal) {
	dir, err := fsafe.OpenDir(h.StagingDirectory)
	if err != nil {
		return nil, refuse(CodeNotConfigured, "the staging directory cannot be opened safely")
	}
	o, err := dir.Owner()
	if err != nil || o.UID != h.TrustOwner || o.Mode&0o077 != 0 {
		_ = dir.Close()
		return nil, refuse(CodeNotConfigured, "the staging directory is not private to root")
	}
	return dir, nil
}

func tlsConfigured(in config.Instance) *Refusal {
	if in.TLSCertificateFile == "" || in.TLSKeyFile == "" {
		return refuse(CodeNotConfigured, "the operator did not configure TLS files for cluster %s", in.LocalName)
	}
	return nil
}

func tlsGenerateKey(_ context.Context, h *Helper, job *verify.Job) (canon.Object, *Refusal) {
	var args struct {
		Cluster     clusterRef `json:"cluster"`
		DNSNames    []string   `json:"dnsNames"`
		IPAddresses []string   `json:"ipAddresses"`
	}
	if r := decodeArgs(job, &args); r != nil {
		return nil, r
	}
	in, r := h.instance(args.Cluster)
	if r != nil {
		return nil, r
	}
	if r := tlsConfigured(in); r != nil {
		return nil, r
	}
	dir, r := h.staging()
	if r != nil {
		return nil, r
	}
	defer dir.Close()
	files, err := dir.Files()
	if err != nil {
		return nil, refuse(CodeFailed, "the staging directory cannot be listed")
	}
	live := 0
	for _, f := range files {
		if h.Clock.Now().Sub(f.ModTime) > stagedKeyTTL {
			_ = dir.Remove(f.Name)
			continue
		}
		live++
	}
	if live >= maxStagedKeys {
		return nil, refuse(CodePreconditionFailed, "too many staged keys")
	}
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, refuse(CodeFailed, "the key could not be generated")
	}
	der, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, refuse(CodeFailed, "the key could not be encoded")
	}
	point, err := nodecrypto.P256PublicKey(&key.PublicKey)
	if err != nil {
		return nil, refuse(CodeFailed, "the key could not be encoded")
	}
	publicKey := nodecrypto.B64U(point)
	proof, err := nodecrypto.SignP256(key, nodecrypto.PgTLSProofValue(job.JobID, publicKey))
	if err != nil {
		return nil, refuse(CodeFailed, "the proof could not be signed")
	}
	id, err := newStagingID()
	if err != nil {
		return nil, refuse(CodeFailed, "no staging id")
	}
	// The staged key takes the staging directory's owner and group (root's
	// on a host, checked by staging), never a group fixed here.
	o, err := dir.Owner()
	if err != nil {
		return nil, refuse(CodeFailed, "the key could not be staged")
	}
	if r := h.admitEffect(OpTLSGenerateKey, job); r != nil {
		return nil, r
	}
	keyPEM := pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: der})
	if err := dir.Create(id+stagedKeySuffix, keyPEM, fsafe.Owner{UID: o.UID, GID: o.GID, Mode: 0o600}); err != nil {
		return nil, refuse(CodeFailed, "the key could not be staged")
	}
	return canon.Object{
		{Name: "stagingId", Value: canon.String(id)},
		{Name: "publicKey", Value: canon.String(publicKey)},
		{Name: "proof", Value: canon.String(proof)},
	}, nil
}

func fingerprint(der []byte) string {
	sum := sha256.Sum256(der)
	return "sha256:" + hex.EncodeToString(sum[:])
}

// certificateFingerprint is the fingerprint of the first certificate in a
// PEM file; an absent file is nil.
func certificateFingerprint(cur fsafe.Previous) (*string, error) {
	if !cur.Existed {
		return nil, nil
	}
	data := cur.Content
	for {
		var block *pem.Block
		block, data = pem.Decode(data)
		if block == nil {
			return nil, errors.New("helper: the certificate file has no certificate")
		}
		if block.Type == "CERTIFICATE" {
			fp := fingerprint(block.Bytes)
			return &fp, nil
		}
	}
}

// pairTarget is one file of the pair to install.
type pairTarget struct {
	dir     *fsafe.Dir
	name    string
	cur     fsafe.Previous
	content []byte
	owner   fsafe.Owner
}

func tlsInstall(_ context.Context, h *Helper, job *verify.Job) (canon.Object, *Refusal) {
	// A job that had its effect is refused as such before anything is read
	// (its staged key is gone, its preconditions no longer hold).
	if len(h.Ledger.Ops(job.JobID)) > 0 {
		return nil, refuse(CodeReplayed, "the job already had its effect")
	}
	var args struct {
		Cluster                    clusterRef `json:"cluster"`
		StagingID                  string     `json:"stagingId"`
		PublicKey                  string     `json:"publicKey"`
		CertificateChain           []string   `json:"certificateChain"`
		ExpectedCurrentFingerprint *string    `json:"expectedCurrentFingerprint"`
	}
	if r := decodeArgs(job, &args); r != nil {
		return nil, r
	}
	if !validStagingID(args.StagingID) || len(args.CertificateChain) == 0 {
		return nil, refuse(CodeJobInvalid, "the staging id or chain is invalid")
	}
	in, r := h.instance(args.Cluster)
	if r != nil {
		return nil, r
	}
	if r := tlsConfigured(in); r != nil {
		return nil, r
	}
	if h.stateDirectory() == "" {
		return nil, refuse(CodeNotConfigured, "the helper has no state directory for its TLS installation record")
	}
	staging, r := h.staging()
	if r != nil {
		return nil, r
	}
	defer staging.Close()
	keyPEM, _, err := staging.ReadFile(args.StagingID+stagedKeySuffix, 16*1024)
	if err != nil {
		return nil, refuse(CodePreconditionFailed, "no staged key with that id")
	}
	block, _ := pem.Decode(keyPEM)
	if block == nil {
		return nil, refuse(CodeFailed, "the staged key cannot be read")
	}
	parsed, err := x509.ParsePKCS8PrivateKey(block.Bytes)
	key, ok := parsed.(*ecdsa.PrivateKey)
	if err != nil || !ok {
		return nil, refuse(CodeFailed, "the staged key cannot be read")
	}
	point, err := nodecrypto.P256PublicKey(&key.PublicKey)
	if err != nil || nodecrypto.B64U(point) != args.PublicKey {
		return nil, refuse(CodePreconditionFailed, "the staged key is not the planned key")
	}
	// The chain: each certificate parses, the first holds the staged key and
	// is valid now, each is signed by the next.
	chain := make([]*x509.Certificate, 0, len(args.CertificateChain))
	var chainPEM []byte
	for _, c := range args.CertificateChain {
		der, ok := nodecrypto.FromB64U(c)
		if !ok {
			return nil, refuse(CodeJobInvalid, "a certificate is not base64url")
		}
		cert, err := x509.ParseCertificate(der)
		if err != nil {
			return nil, refuse(CodeJobInvalid, "a certificate does not parse")
		}
		chain = append(chain, cert)
		chainPEM = append(chainPEM, pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der})...)
	}
	leaf := chain[0]
	leafKey, ok := leaf.PublicKey.(*ecdsa.PublicKey)
	now := h.Clock.Now()
	if !ok || !leafKey.Equal(&key.PublicKey) {
		return nil, refuse(CodePreconditionFailed, "the certificate is not for the staged key")
	}
	if now.Before(leaf.NotBefore.Add(-clock.Tolerance)) || !now.Before(leaf.NotAfter) {
		return nil, refuse(CodePreconditionFailed, "the certificate is not valid now")
	}
	for i := 0; i+1 < len(chain); i++ {
		if chain[i].CheckSignatureFrom(chain[i+1]) != nil {
			return nil, refuse(CodePreconditionFailed, "the chain does not verify")
		}
	}
	certDir, certName, r := h.file(in.TLSCertificateFile)
	if r != nil {
		return nil, r
	}
	defer certDir.Close()
	keyDir, keyName, r := h.file(in.TLSKeyFile)
	if r != nil {
		return nil, r
	}
	defer keyDir.Close()
	// The pair as it is now: what the record keeps as the previous pair.
	certCur, err := certDir.Current(certName, maxFile)
	if err != nil {
		return nil, refuse(CodePreconditionFailed, "the current certificate cannot be read safely")
	}
	current, err := certificateFingerprint(certCur)
	if err != nil {
		return nil, refuse(CodePreconditionFailed, "the current certificate cannot be read safely")
	}
	switch {
	case args.ExpectedCurrentFingerprint == nil && current != nil,
		args.ExpectedCurrentFingerprint != nil && (current == nil || *current != *args.ExpectedCurrentFingerprint):
		return nil, refuse(CodePreconditionFailed, "the certificate changed since the plan")
	}
	keyCur, err := keyDir.Current(keyName, maxFile)
	if err != nil {
		return nil, refuse(CodePreconditionFailed, "the current key cannot be read safely")
	}
	owner, r := h.dataOwner(in)
	if r != nil {
		return nil, r
	}
	der, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, refuse(CodeFailed, "the key cannot be encoded")
	}
	state, stateOwner, err := h.stateDir()
	if err != nil {
		return nil, refuse(CodeNotConfigured, "the helper's state directory cannot be used safely")
	}
	defer state.Close()
	if r := h.admitEffect(OpTLSInstall, job); r != nil {
		return nil, r
	}
	keyFile := pairTarget{dir: keyDir, name: keyName, cur: keyCur,
		content: pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: der}),
		owner:   fsafe.Owner{UID: owner.UID, GID: owner.GID, Mode: 0o600}}
	certFile := pairTarget{dir: certDir, name: certName, cur: certCur, content: chainPEM,
		owner: fsafe.Owner{UID: owner.UID, GID: owner.GID, Mode: 0o644}}
	rec := &pairRecord{
		Schema: pairRecordSchema, State: pairPrepared, JobID: job.JobID, Cluster: in.LocalName,
		Key:         pairFileOf(in.TLSKeyFile, keyCur, keyFile.content, keyFile.owner),
		Certificate: pairFileOf(in.TLSCertificateFile, certCur, certFile.content, certFile.owner),
	}
	if err := installPair(state, stateOwner, rec, keyFile, certFile); err != nil {
		// What is on disk now is decided from the record alone, as at a
		// restart: the new pair completed, the previous one put back, or,
		// when even that fails, left to the next settling.
		out, blocked := h.settlePair()
		switch {
		case blocked != nil:
			return nil, refuse(CodeOutcomeUnknown, "the TLS files of cluster %s could not be installed and the previous key and certificate "+
				"are not back yet; the helper settles this before any other change", in.LocalName)
		case out.record == nil || out.record.JobID != job.JobID:
			return nil, refuse(CodeFailed, "the TLS files of cluster %s could not be installed; nothing was changed", in.LocalName)
		case out.state != pairCommitted:
			return nil, refuse(CodeFailed, "the TLS files of cluster %s could not be installed; the previous key and certificate are in place", in.LocalName)
		}
		// Committed: both files hold the new pair, durably.
	}
	_ = staging.Remove(args.StagingID + stagedKeySuffix)
	previous := canon.Value(canon.Null{})
	if current != nil {
		previous = canon.String(*current)
	}
	return canon.Object{
		{Name: "fingerprint", Value: canon.String(fingerprint(leaf.Raw))},
		{Name: "previousFingerprint", Value: previous},
		{Name: "notAfter", Value: canon.String(leaf.NotAfter.UTC().Format(time.RFC3339))},
	}, nil
}

// installPair installs the key and the certificate as one change: the
// record first (nothing of the pair touched before it is durable), the
// previous contents kept, the key, the certificate, the record committed and
// removed. An error leaves the record for settlePair to decide from.
func installPair(state *fsafe.Dir, stateOwner fsafe.Owner, rec *pairRecord, key, cert pairTarget) error {
	if err := writePairRecord(state, stateOwner, rec); err != nil {
		return err
	}
	for _, f := range []pairTarget{key, cert} {
		if err := f.dir.KeepPrevious(f.name, f.cur); err != nil {
			return err
		}
	}
	for _, f := range []pairTarget{key, cert} {
		if err := f.dir.Install(f.name, f.content, f.owner); err != nil {
			return err
		}
	}
	rec.State = pairCommitted
	if err := writePairRecord(state, stateOwner, rec); err != nil {
		return err
	}
	// A committed record left behind (the removal failed) stops nothing.
	_ = state.Remove(pairRecordName)
	return nil
}
